-- Grammar Mastery Platform — Stage 12 canonical PostgreSQL relational contract
-- Semantic version: relational-schema-v0.9.0 | PostgreSQL 15+
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
DO $$ BEGIN CREATE TYPE question_status AS ENUM ('DRAFT','READY_FOR_REVIEW','CHANGES_REQUESTED','APPROVED','PUBLISHED','REJECTED','RETIRED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE difficulty_code AS ENUM ('EASY','MEDIUM','HARD','VERY_HARD'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE question_locale AS ENUM ('fr-FR','fa-IR'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE source_type AS ENUM ('BOOK_DIRECT','PROJECT_SYNTHETIC_FROM_RULE','EXTERNAL_REVIEWED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE cognitive_level AS ENUM ('RECALL','APPLICATION','DISCRIMINATION'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE compatibility_status AS ENUM ('PREFERRED','ALLOWED','CONDITIONAL','NOT_SUITABLE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE user_status AS ENUM ('ACTIVE','DISABLED','DELETED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE test_mode AS ENUM ('CUSTOM','SINGLE_LESSON','MULTI_LESSON','CATEGORY','TCF','ADAPTIVE','REVIEW','MISTAKES'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE attempt_status AS ENUM ('IN_PROGRESS','COMPLETED','ABANDONED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE learning_review_status AS ENUM ('SCHEDULED','DUE','COMPLETED','SUSPENDED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS system_versions(component varchar(100) PRIMARY KEY,version varchar(120) NOT NULL,status varchar(80) NOT NULL,source_ref text,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_decisions(decision_code varchar(100) PRIMARY KEY,scope varchar(100) NOT NULL,status varchar(80) NOT NULL,decision_fa text NOT NULL,impact text,owner varchar(120),upstream_stage smallint,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS grammar_categories(id uuid PRIMARY KEY,code varchar(20) NOT NULL UNIQUE,slug varchar(100) NOT NULL UNIQUE,node_kind varchar(20) NOT NULL CHECK(node_kind IN ('CATEGORY','SUBCATEGORY')),parent_id uuid REFERENCES grammar_categories(id) ON DELETE RESTRICT,display_name_fr varchar(200) NOT NULL,display_name_fa varchar(200),membership_rule_fa text,display_order int NOT NULL DEFAULT 0,status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ARCHIVED')),taxonomy_version varchar(100) NOT NULL,CHECK((node_kind='CATEGORY' AND parent_id IS NULL) OR (node_kind='SUBCATEGORY' AND parent_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS grammar_lessons(id uuid PRIMARY KEY,lesson_no smallint NOT NULL UNIQUE,title_fr_official varchar(255) NOT NULL,system_short_title varchar(100) NOT NULL UNIQUE,category_id uuid NOT NULL REFERENCES grammar_categories(id) ON DELETE RESTRICT,subcategory_id uuid NOT NULL REFERENCES grammar_categories(id) ON DELETE RESTRICT,tcf_weight numeric(8,4) NOT NULL DEFAULT 0 CHECK(tcf_weight>=0),book_pages varchar(120),pdf_pages varchar(120),source_ref text NOT NULL,active boolean NOT NULL DEFAULT true,extraction_status varchar(80),content_version varchar(100) NOT NULL,taxonomy_version varchar(100) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS grammar_subtopics(id uuid PRIMARY KEY,lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,subtopic_code varchar(30) NOT NULL UNIQUE,title_fr varchar(255) NOT NULL,title_fa varchar(255),short_definition_fa text,teaching_note_fa text,exceptions_register_note text,source_book_pages varchar(100),source_pdf_pages varchar(100),source_ref text NOT NULL,source_basis varchar(100),translation_status varchar(100),content_version varchar(100) NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lesson_prerequisites(lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,prerequisite_lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,strength smallint NOT NULL DEFAULT 3 CHECK(strength BETWEEN 1 AND 5),relation_type varchar(50) NOT NULL DEFAULT 'PREREQUISITE',evidence_type varchar(120),status varchar(100),note_fa text,PRIMARY KEY(lesson_id,prerequisite_lesson_id),CHECK(lesson_id<>prerequisite_lesson_id));
CREATE TABLE IF NOT EXISTS lesson_related_references(relation_id uuid PRIMARY KEY,lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,related_lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,relation_type varchar(80) NOT NULL,strength smallint CHECK(strength BETWEEN 1 AND 5),evidence_type varchar(120),status varchar(100),note_fa text,CHECK(lesson_id<>related_lesson_id));
CREATE TABLE IF NOT EXISTS tags(id uuid PRIMARY KEY,code varchar(20) NOT NULL UNIQUE,slug varchar(100) NOT NULL UNIQUE,tag_group varchar(80),display_name_fr varchar(200) NOT NULL,display_name_fa varchar(200),membership_rule_fa text,status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ARCHIVED')),taxonomy_version varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS lesson_tags(lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,tag_id uuid NOT NULL REFERENCES tags(id) ON DELETE RESTRICT,assignment_order int,assignment_basis text,taxonomy_version varchar(100) NOT NULL,PRIMARY KEY(lesson_id,tag_id));
CREATE TABLE IF NOT EXISTS question_types(id uuid PRIMARY KEY,code varchar(40) NOT NULL UNIQUE,name_fa varchar(200) NOT NULL,system_name_en varchar(200),cognitive_level cognitive_level NOT NULL,response_mode varchar(40) NOT NULL DEFAULT 'SINGLE_CHOICE_4' CHECK(response_mode='SINGLE_CHOICE_4'),active boolean NOT NULL DEFAULT true,catalogue_version varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS misconceptions(id uuid PRIMARY KEY,subtopic_id uuid NOT NULL REFERENCES grammar_subtopics(id) ON DELETE RESTRICT,family varchar(80) NOT NULL,name_fa varchar(200),statement_fa text NOT NULL,diagnostic_interpretation_fa text,distractor_authoring_hint_fa text,priority varchar(50),status varchar(100) NOT NULL,empirical_commonness varchar(100),catalogue_version varchar(100) NOT NULL,source_ref text);
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email citext UNIQUE,display_name varchar(200),locale varchar(20) NOT NULL DEFAULT 'fa-IR',timezone varchar(80) NOT NULL DEFAULT 'UTC',status user_status NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS actors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),external_actor_id varchar(100) NOT NULL UNIQUE,actor_type varchar(30) NOT NULL CHECK(actor_type IN ('USER','CONTENT_AUTHOR','REVIEWER','ADMIN','SERVICE','AI_GENERATOR','SYSTEM')),display_name varchar(200),user_id uuid REFERENCES users(id) ON DELETE RESTRICT,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_uid uuid NOT NULL,external_id varchar(100) NOT NULL,revision int NOT NULL CHECK(revision>=1),parent_revision_id uuid REFERENCES questions(id) ON DELETE RESTRICT,lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,primary_subtopic_id uuid NOT NULL REFERENCES grammar_subtopics(id) ON DELETE RESTRICT,question_type_id uuid NOT NULL REFERENCES question_types(id) ON DELETE RESTRICT,stem text NOT NULL CHECK(length(stem)<=2000),stem_locale question_locale NOT NULL,full_explanation text NOT NULL CHECK(length(full_explanation)<=4000),explanation_locale question_locale NOT NULL,initial_difficulty_code difficulty_code NOT NULL,initial_difficulty_score numeric(4,2) CHECK(initial_difficulty_score BETWEEN 1 AND 4),difficulty_model_version varchar(100) NOT NULL,status question_status NOT NULL DEFAULT 'DRAFT',source_type source_type NOT NULL,source_ref text NOT NULL,author_actor_id uuid NOT NULL REFERENCES actors(id) ON DELETE RESTRICT,reviewer_actor_id uuid REFERENCES actors(id) ON DELETE RESTRICT,correct_option_id uuid,fingerprint_sha256 char(64) NOT NULL UNIQUE,guardrail_satisfied boolean NOT NULL DEFAULT false,taxonomy_version varchar(100) NOT NULL,question_type_catalogue_version varchar(100) NOT NULL,compatibility_version varchar(100) NOT NULL,distractor_rules_version varchar(100) NOT NULL,content_version varchar(100) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),submitted_at timestamptz,approved_at timestamptz,published_at timestamptz,retired_at timestamptz,UNIQUE(external_id,revision),UNIQUE(question_uid,revision));
CREATE TABLE IF NOT EXISTS question_options(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,position char(1) NOT NULL CHECK(position IN ('A','B','C','D')),option_text text NOT NULL CHECK(length(option_text)<=500),locale question_locale NOT NULL,explanation text NOT NULL CHECK(length(explanation)<=2000),misconception_id uuid REFERENCES misconceptions(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(question_id,position));
DO $$ BEGIN ALTER TABLE questions ADD CONSTRAINT fk_questions_correct_option FOREIGN KEY(correct_option_id) REFERENCES question_options(id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS question_secondary_subtopics(question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,subtopic_id uuid NOT NULL REFERENCES grammar_subtopics(id) ON DELETE RESTRICT,PRIMARY KEY(question_id,subtopic_id));
CREATE TABLE IF NOT EXISTS question_tags(question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,tag_id uuid NOT NULL REFERENCES tags(id) ON DELETE RESTRICT,PRIMARY KEY(question_id,tag_id));
CREATE TABLE IF NOT EXISTS question_media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,media_type varchar(10) NOT NULL CHECK(media_type IN ('IMAGE','AUDIO','VIDEO')),uri text NOT NULL,alt_text text,transcript text,source_ref text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(media_type<>'IMAGE' OR nullif(btrim(alt_text),'') IS NOT NULL),CHECK(media_type NOT IN ('AUDIO','VIDEO') OR nullif(btrim(transcript),'') IS NOT NULL));
CREATE TABLE IF NOT EXISTS lesson_question_type_compatibility(id uuid PRIMARY KEY,lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,question_type_id uuid NOT NULL REFERENCES question_types(id) ON DELETE RESTRICT,compatibility_status compatibility_status NOT NULL,allocation_factor numeric(6,4) NOT NULL CHECK(allocation_factor>=0),conditional_guardrail_required boolean NOT NULL DEFAULT false,rationale text,compatibility_version varchar(100) NOT NULL,UNIQUE(lesson_id,question_type_id,compatibility_version));
CREATE TABLE IF NOT EXISTS subtopic_question_type_compatibility(id uuid PRIMARY KEY,subtopic_id uuid NOT NULL REFERENCES grammar_subtopics(id) ON DELETE RESTRICT,question_type_id uuid NOT NULL REFERENCES question_types(id) ON DELETE RESTRICT,compatibility_status compatibility_status NOT NULL,allocation_factor numeric(6,4) NOT NULL CHECK(allocation_factor>=0),conditional_guardrail_required boolean NOT NULL DEFAULT false,guardrail_text text,compatibility_version varchar(100) NOT NULL,UNIQUE(subtopic_id,question_type_id,compatibility_version));
CREATE TABLE IF NOT EXISTS question_type_global_targets(question_type_id uuid NOT NULL REFERENCES question_types(id) ON DELETE RESTRICT,policy_version varchar(100) NOT NULL,target_full int NOT NULL CHECK(target_full>=0),target_expanded int NOT NULL CHECK(target_expanded>=0),target_mvp int NOT NULL CHECK(target_mvp>=0),PRIMARY KEY(question_type_id,policy_version),CHECK(target_mvp<=target_expanded AND target_expanded<=target_full));
CREATE TABLE IF NOT EXISTS lesson_weight_versions(lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,weight_model_version varchar(100) NOT NULL,frequency_score numeric(6,3),comprehension_score numeric(6,3),production_score numeric(6,3),error_propensity_score numeric(6,3),dependency_score numeric(6,3),final_weight_pct numeric(8,4) NOT NULL CHECK(final_weight_pct>=0),rationale text,effective_at timestamptz NOT NULL,PRIMARY KEY(lesson_id,weight_model_version));
CREATE TABLE IF NOT EXISTS lesson_capacity_targets(lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,capacity_model_version varchar(100) NOT NULL,target_full int NOT NULL CHECK(target_full>=0),target_expanded int NOT NULL CHECK(target_expanded>=0),target_mvp int NOT NULL CHECK(target_mvp>=0),PRIMARY KEY(lesson_id,capacity_model_version),CHECK(target_mvp<=target_expanded AND target_expanded<=target_full));
CREATE TABLE IF NOT EXISTS difficulty_profiles(profile_code varchar(40) PRIMARY KEY,easy_pct numeric(6,5) NOT NULL,medium_pct numeric(6,5) NOT NULL,hard_pct numeric(6,5) NOT NULL,very_hard_pct numeric(6,5) NOT NULL,policy_version varchar(100) NOT NULL,CHECK(abs((easy_pct+medium_pct+hard_pct+very_hard_pct)-1)<.000001));
CREATE TABLE IF NOT EXISTS lesson_difficulty_targets(lesson_id uuid NOT NULL REFERENCES grammar_lessons(id) ON DELETE RESTRICT,policy_version varchar(100) NOT NULL,profile_code varchar(40) NOT NULL REFERENCES difficulty_profiles(profile_code) ON DELETE RESTRICT,target_full int NOT NULL,easy_full int NOT NULL,medium_full int NOT NULL,hard_full int NOT NULL,very_hard_full int NOT NULL,target_expanded int NOT NULL,target_mvp int NOT NULL,rationale text,PRIMARY KEY(lesson_id,policy_version),CHECK(easy_full+medium_full+hard_full+very_hard_full=target_full));
CREATE TABLE IF NOT EXISTS bank_targets(target_key varchar(100) NOT NULL,target_scope varchar(40) NOT NULL,target_full int NOT NULL CHECK(target_full>=0),target_expanded int NOT NULL CHECK(target_expanded>=0),target_mvp int NOT NULL CHECK(target_mvp>=0),policy_version varchar(100) NOT NULL,note text,PRIMARY KEY(target_key,target_scope,policy_version));
CREATE TABLE IF NOT EXISTS tests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id) ON DELETE RESTRICT,mode test_mode NOT NULL,title varchar(255),config jsonb NOT NULL DEFAULT '{}'::jsonb,selection_model_version varchar(100),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS test_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),test_id uuid NOT NULL REFERENCES tests(id) ON DELETE RESTRICT,question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,position int NOT NULL CHECK(position>=1),selection_reason text,selection_score numeric,question_snapshot jsonb NOT NULL,option_snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(test_id,position),UNIQUE(test_id,question_id));
CREATE TABLE IF NOT EXISTS test_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),test_id uuid NOT NULL REFERENCES tests(id) ON DELETE RESTRICT,user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,status attempt_status NOT NULL,started_at timestamptz NOT NULL,completed_at timestamptz,score_raw numeric,score_pct numeric CHECK(score_pct BETWEEN 0 AND 100),mastery_model_version varchar(100),client_metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_answers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL REFERENCES test_attempts(id) ON DELETE RESTRICT,test_question_id uuid NOT NULL REFERENCES test_questions(id) ON DELETE RESTRICT,selected_option_id uuid REFERENCES question_options(id) ON DELETE RESTRICT,answer_sequence int NOT NULL DEFAULT 1 CHECK(answer_sequence>=1),is_correct boolean,response_ms int CHECK(response_ms>=0),answered_at timestamptz NOT NULL,answer_metadata jsonb,UNIQUE(attempt_id,test_question_id,answer_sequence));
CREATE TABLE IF NOT EXISTS user_mastery(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,scope_type varchar(20) NOT NULL CHECK(scope_type IN ('LESSON','SUBTOPIC','CATEGORY','TAG')),scope_id uuid NOT NULL,mastery_score numeric(6,3) NOT NULL CHECK(mastery_score BETWEEN 0 AND 100),confidence numeric(5,4) NOT NULL CHECK(confidence BETWEEN 0 AND 1),evidence_count int NOT NULL DEFAULT 0 CHECK(evidence_count>=0),mastery_model_version varchar(100) NOT NULL,last_evidence_at timestamptz,updated_at timestamptz NOT NULL,UNIQUE(user_id,scope_type,scope_id,mastery_model_version));
CREATE TABLE IF NOT EXISTS mastery_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,scope_type varchar(20) NOT NULL CHECK(scope_type IN ('LESSON','SUBTOPIC','CATEGORY','TAG')),scope_id uuid NOT NULL,mastery_score numeric(6,3) NOT NULL CHECK(mastery_score BETWEEN 0 AND 100),confidence numeric(5,4) NOT NULL CHECK(confidence BETWEEN 0 AND 1),evidence_count int NOT NULL DEFAULT 0,mastery_model_version varchar(100) NOT NULL,captured_at timestamptz NOT NULL,source_event varchar(100));
CREATE TABLE IF NOT EXISTS review_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,target_type varchar(20) NOT NULL CHECK(target_type IN ('QUESTION','SUBTOPIC')),question_id uuid REFERENCES questions(id) ON DELETE RESTRICT,subtopic_id uuid REFERENCES grammar_subtopics(id) ON DELETE RESTRICT,status learning_review_status NOT NULL,due_at timestamptz NOT NULL,interval_days numeric(8,2) NOT NULL CHECK(interval_days>=0),strength numeric(8,4),lapse_count int NOT NULL DEFAULT 0,scheduler_version varchar(100) NOT NULL,last_answer_id uuid REFERENCES user_answers(id) ON DELETE RESTRICT,updated_at timestamptz NOT NULL,CHECK(question_id IS NOT NULL OR subtopic_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS question_metrics(question_id uuid PRIMARY KEY REFERENCES questions(id) ON DELETE RESTRICT,attempts int NOT NULL DEFAULT 0,correct_rate numeric(6,5),avg_response_ms numeric,discrimination numeric,skip_rate numeric(6,5),observed_difficulty_score numeric(4,2),observed_difficulty_confidence varchar(10) CHECK(observed_difficulty_confidence IN ('NONE','LOW','MEDIUM','HIGH')),metric_version varchar(100),updated_at timestamptz);
CREATE TABLE IF NOT EXISTS question_option_metrics(question_option_id uuid PRIMARY KEY REFERENCES question_options(id) ON DELETE RESTRICT,selected_count int NOT NULL DEFAULT 0,selection_rate numeric(6,5),updated_at timestamptz);
CREATE TABLE IF NOT EXISTS import_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_name varchar(255) NOT NULL,schema_version varchar(100) NOT NULL,content_version varchar(100) NOT NULL,status varchar(20) NOT NULL CHECK(status IN ('PREVIEW','VALIDATED','COMMITTED','ROLLED_BACK','FAILED')),row_count int NOT NULL DEFAULT 0,valid_count int NOT NULL DEFAULT 0,rejected_count int NOT NULL DEFAULT 0,checksum_sha256 char(64),created_by_actor_id uuid REFERENCES actors(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL,committed_at timestamptz,rollback_of_batch_id uuid REFERENCES import_batches(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS qa_transition_rules(id uuid PRIMARY KEY,transition_code varchar(20) NOT NULL UNIQUE,from_state varchar(40) NOT NULL,action varchar(80) NOT NULL,to_state varchar(40) NOT NULL,allowed boolean NOT NULL,actor_role varchar(120),physical_operation varchar(80) NOT NULL,audit_event_required varchar(100) NOT NULL,workflow_version varchar(100) NOT NULL,notes_fa text);
CREATE TABLE IF NOT EXISTS question_status_events(id bigserial PRIMARY KEY,question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,from_status varchar(40),to_status varchar(40) NOT NULL,action varchar(80) NOT NULL,actor_id uuid REFERENCES actors(id) ON DELETE RESTRICT,event_metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS question_validation_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,validator_version varchar(100) NOT NULL,result varchar(20) NOT NULL CHECK(result IN ('PASS','FAIL')),error_codes jsonb,run_metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS question_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,reviewer_actor_id uuid NOT NULL REFERENCES actors(id) ON DELETE RESTRICT,disposition varchar(30) NOT NULL CHECK(disposition IN ('APPROVED','CHANGES_REQUESTED','REJECTED')),review_notes text,workflow_version varchar(100) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rejection_reasons(id uuid PRIMARY KEY,reason_code varchar(60) NOT NULL UNIQUE,category varchar(80),blocking boolean NOT NULL DEFAULT true,label_fa varchar(255) NOT NULL,description_fa text,workflow_version varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS question_rejections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,review_id uuid REFERENCES question_reviews(id) ON DELETE RESTRICT,reason_id uuid NOT NULL REFERENCES rejection_reasons(id) ON DELETE RESTRICT,reviewer_actor_id uuid REFERENCES actors(id) ON DELETE RESTRICT,note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS review_queue_classes(queue_class varchar(50) PRIMARY KEY,priority_rank int NOT NULL UNIQUE,eligibility_fa text NOT NULL,ordering_fa text NOT NULL,required_action_fa text NOT NULL,may_bypass_machine_validation boolean NOT NULL DEFAULT false CHECK(NOT may_bypass_machine_validation),may_bypass_independent_review boolean NOT NULL DEFAULT false CHECK(NOT may_bypass_independent_review),queue_version varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS content_review_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,queue_class varchar(50) NOT NULL REFERENCES review_queue_classes(queue_class) ON DELETE RESTRICT,status varchar(20) NOT NULL CHECK(status IN ('OPEN','CLAIMED','COMPLETED','CANCELLED')),priority_score numeric,due_at timestamptz,assigned_reviewer_actor_id uuid REFERENCES actors(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uq_content_review_queue_one_open ON content_review_queue(question_id) WHERE status IN ('OPEN','CLAIMED');
CREATE TABLE IF NOT EXISTS user_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,reporting_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,report_type varchar(80) NOT NULL,severity varchar(20) NOT NULL CHECK(severity IN ('CRITICAL','HIGH','MEDIUM','LOW')),description text,status varchar(20) NOT NULL CHECK(status IN ('OPEN','TRIAGED','CLOSED','BACKLOG')),created_at timestamptz NOT NULL,triaged_at timestamptz,resolution text);
CREATE TABLE IF NOT EXISTS serving_overrides(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,enabled boolean NOT NULL,reason text NOT NULL,source_report_id uuid REFERENCES user_reports(id) ON DELETE RESTRICT,created_by_actor_id uuid REFERENCES actors(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL,expires_at timestamptz,revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS publish_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_code varchar(100) NOT NULL UNIQUE,status varchar(20) NOT NULL CHECK(status IN ('OPEN','COMMITTED','CANCELLED')),created_by_actor_id uuid REFERENCES actors(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL,committed_at timestamptz);
CREATE TABLE IF NOT EXISTS publish_batch_questions(publish_batch_id uuid NOT NULL REFERENCES publish_batches(id) ON DELETE RESTRICT,question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,PRIMARY KEY(publish_batch_id,question_id));
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,actor_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,actor_id uuid REFERENCES actors(id) ON DELETE RESTRICT,action varchar(80) NOT NULL,entity_type varchar(80) NOT NULL,entity_id uuid,before_data jsonb,after_data jsonb,ip_hash varchar(128),request_id varchar(128),created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE VIEW v_current_questions AS SELECT q.* FROM questions q WHERE NOT EXISTS (SELECT 1 FROM questions n WHERE n.question_uid=q.question_uid AND n.revision>q.revision);
CREATE OR REPLACE VIEW v_serving_questions AS SELECT q.* FROM v_current_questions q WHERE q.status='PUBLISHED' AND NOT EXISTS (SELECT 1 FROM serving_overrides s WHERE s.question_id=q.id AND s.enabled=false AND s.revoked_at IS NULL AND (s.expires_at IS NULL OR s.expires_at>now()));
CREATE OR REPLACE VIEW v_question_inventory AS SELECT l.id lesson_id,l.lesson_no,q.initial_difficulty_code difficulty,count(q.id) FILTER(WHERE q.status='PUBLISHED') published_count,count(q.id) FILTER(WHERE q.status='APPROVED') approved_count FROM grammar_lessons l LEFT JOIN questions q ON q.lesson_id=l.id GROUP BY l.id,l.lesson_no,q.initial_difficulty_code;
CREATE OR REPLACE FUNCTION s12_block_append_update_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only table'; END $$;
DROP TRIGGER IF EXISTS trg_user_answers_append_only ON user_answers; CREATE TRIGGER trg_user_answers_append_only BEFORE UPDATE OR DELETE ON user_answers FOR EACH ROW EXECUTE FUNCTION s12_block_append_update_delete();
DROP TRIGGER IF EXISTS trg_mastery_snapshots_append_only ON mastery_snapshots; CREATE TRIGGER trg_mastery_snapshots_append_only BEFORE UPDATE OR DELETE ON mastery_snapshots FOR EACH ROW EXECUTE FUNCTION s12_block_append_update_delete();
DROP TRIGGER IF EXISTS trg_question_status_events_append_only ON question_status_events; CREATE TRIGGER trg_question_status_events_append_only BEFORE UPDATE OR DELETE ON question_status_events FOR EACH ROW EXECUTE FUNCTION s12_block_append_update_delete();
DROP TRIGGER IF EXISTS trg_audit_logs_append_only ON audit_logs; CREATE TRIGGER trg_audit_logs_append_only BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION s12_block_append_update_delete();
CREATE OR REPLACE FUNCTION s12_ready_for_review_gate() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE n int; BEGIN IF NEW.status='READY_FOR_REVIEW' AND NEW.status IS DISTINCT FROM OLD.status THEN SELECT count(*) INTO n FROM question_options WHERE question_id=NEW.id; IF n<>4 THEN RAISE EXCEPTION 'review gate: exactly four options required'; END IF; IF NEW.correct_option_id IS NULL OR NOT EXISTS(SELECT 1 FROM question_options WHERE id=NEW.correct_option_id AND question_id=NEW.id) THEN RAISE EXCEPTION 'review gate: valid correct option required'; END IF; IF EXISTS(SELECT 1 FROM question_options WHERE question_id=NEW.id AND id<>NEW.correct_option_id AND misconception_id IS NULL) THEN RAISE EXCEPTION 'review gate: every distractor needs misconception mapping'; END IF; IF EXISTS(SELECT 1 FROM question_options WHERE id=NEW.correct_option_id AND misconception_id IS NOT NULL) THEN RAISE EXCEPTION 'review gate: correct option must not map misconception'; END IF; IF NOT EXISTS(SELECT 1 FROM question_validation_runs WHERE question_id=NEW.id AND result='PASS') THEN RAISE EXCEPTION 'review gate: machine validation PASS required'; END IF; IF EXISTS(SELECT 1 FROM subtopic_question_type_compatibility c WHERE c.subtopic_id=NEW.primary_subtopic_id AND c.question_type_id=NEW.question_type_id AND c.compatibility_version=NEW.compatibility_version AND (c.compatibility_status='NOT_SUITABLE' OR (c.compatibility_status='CONDITIONAL' AND NOT NEW.guardrail_satisfied))) THEN RAISE EXCEPTION 'review gate: incompatible/unguarded type'; END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_ready_for_review_gate ON questions; CREATE TRIGGER trg_ready_for_review_gate BEFORE UPDATE OF status ON questions FOR EACH ROW EXECUTE FUNCTION s12_ready_for_review_gate();
CREATE OR REPLACE FUNCTION s12_approval_gate() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='APPROVED' AND NEW.status IS DISTINCT FROM OLD.status THEN IF NEW.reviewer_actor_id IS NULL OR NEW.reviewer_actor_id=NEW.author_actor_id THEN RAISE EXCEPTION 'approval gate: independent reviewer required'; END IF; IF NOT EXISTS(SELECT 1 FROM question_reviews r WHERE r.question_id=NEW.id AND r.reviewer_actor_id=NEW.reviewer_actor_id AND r.disposition='APPROVED') THEN RAISE EXCEPTION 'approval gate: approved review record required'; END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_approval_gate ON questions; CREATE TRIGGER trg_approval_gate BEFORE UPDATE OF status ON questions FOR EACH ROW EXECUTE FUNCTION s12_approval_gate();
CREATE OR REPLACE FUNCTION s12_publish_gate() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='PUBLISHED' AND NEW.status IS DISTINCT FROM OLD.status THEN IF OLD.status<>'APPROVED' THEN RAISE EXCEPTION 'publish gate: must publish from APPROVED'; END IF; IF NOT EXISTS(SELECT 1 FROM publish_batch_questions pbq JOIN publish_batches pb ON pb.id=pbq.publish_batch_id WHERE pbq.question_id=NEW.id AND pb.status IN ('OPEN','COMMITTED')) THEN RAISE EXCEPTION 'publish gate: explicit publish batch required'; END IF; NEW.published_at=COALESCE(NEW.published_at,now()); END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_publish_gate ON questions; CREATE TRIGGER trg_publish_gate BEFORE UPDATE OF status ON questions FOR EACH ROW EXECUTE FUNCTION s12_publish_gate();
CREATE OR REPLACE FUNCTION s12_published_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='PUBLISHED' AND (NEW.stem IS DISTINCT FROM OLD.stem OR NEW.full_explanation IS DISTINCT FROM OLD.full_explanation OR NEW.lesson_id IS DISTINCT FROM OLD.lesson_id OR NEW.primary_subtopic_id IS DISTINCT FROM OLD.primary_subtopic_id OR NEW.question_type_id IS DISTINCT FROM OLD.question_type_id OR NEW.correct_option_id IS DISTINCT FROM OLD.correct_option_id) THEN RAISE EXCEPTION 'published content is immutable; create a new revision'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_published_immutable ON questions; CREATE TRIGGER trg_published_immutable BEFORE UPDATE ON questions FOR EACH ROW EXECUTE FUNCTION s12_published_immutable();
CREATE INDEX IF NOT EXISTS idx_questions_uid_revision ON questions(question_uid,revision DESC); CREATE INDEX IF NOT EXISTS idx_questions_serving ON questions(status,lesson_id,initial_difficulty_code); CREATE INDEX IF NOT EXISTS idx_subtopics_lesson ON grammar_subtopics(lesson_id); CREATE INDEX IF NOT EXISTS idx_user_answers_attempt ON user_answers(attempt_id,test_question_id,answer_sequence DESC); CREATE INDEX IF NOT EXISTS idx_mastery_user_scope ON user_mastery(user_id,scope_type,scope_id); CREATE INDEX IF NOT EXISTS idx_review_due ON review_queue(user_id,status,due_at); CREATE INDEX IF NOT EXISTS idx_reports_open ON user_reports(status,severity,created_at); CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_logs(entity_type,entity_id,created_at DESC);
